out = []
i = 0
added = 0
while i < len(lines):
    line = lines[i]
    stripped = line.rstrip("\n")
    if "\u3014\u76ee \u6b21\u3015" in stripped:
        in_toc = True
    if stripped == "## \u7b2c1\u7ae0 \u7dcf \u5247":
        in_toc = False
    out.append(line)
    if in_toc:
        i += 1
        continue
    if stripped in skip_repeated:
        i += 1
        continue
    if stripped == "## \u7b2c3\u7ae0 \u707d\u5bb3\u5fdc\u6025\u5bfe\u7b56\u8a08\u753b":
        if first_ch3_done:
            i += 1
            continue
        first_ch3_done = True
    if stripped in S:
        summary = S[stripped]
        if i + 1 < len(lines) and lines[i + 1].strip() == "":
            already = (i + 2 < len(lines) and lines[i + 2].strip() == summary)
            if not already:
                out.append("\n")
                out.append(summary + "\n")
                added += 1
                i += 2
                continue
    i += 1

with open(filepath, "w") as f:
    f.writelines(out)
print("Added", added, "summaries")
